<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $sale->number }}</title><style>body{font:13px monospace;width:72mm;margin:12px auto;color:#111}h1{text-align:center;font-size:20px}p{margin:8px 0}table{width:100%;border-collapse:collapse}td{padding:5px 0;vertical-align:top}td:last-child{text-align:right}hr{border:0;border-top:1px dashed #555}.actions{margin:15px 0}@media print{body{margin:0 auto}.actions{display:none}@page{margin:4mm}}</style></head><body><h1>Izzi Kebab</h1><p>{{ $sale->branch_name }}<br>{{ $sale->number }}<br>{{ $time }}<br>Kasir: {{ $sale->actor_name }}</p><hr><table>@foreach($lines as $line)<tr><td>{{ $line['menu_name'] }}<br>{{ $line['quantity'] }} × Rp {{ number_format($line['price'],0,',','.') }}@if($line['cancelled_quantity'])<br>Dibatalkan {{ $line['cancelled_quantity'] }}@endif</td><td>Rp {{ number_format(($line['quantity']-$line['cancelled_quantity'])*$line['price'],0,',','.') }}</td></tr>@endforeach</table><hr><p>Total awal: Rp {{ number_format($sale->total,0,',','.') }}<br>Pembatalan: Rp {{ number_format($sale->total-$sale->net_total,0,',','.') }}<br><strong>Total bersih: Rp {{ number_format($sale->net_total,0,',','.') }}</strong><br>{{ $sale->payment_type === 'cash' ? 'Tunai' : 'Transfer' }} awal: Rp {{ number_format($sale->amount_paid,0,',','.') }}<br>Kembalian awal: Rp {{ number_format($sale->amount_paid-$sale->total,0,',','.') }}</p>@if($sale->total > $sale->net_total)<p>Nilai pembatalan perlu diperiksa untuk pengembalian pembayaran.</p>@endif<div class="actions"><button onclick="window.print()">Cetak struk</button></div></body></html>
